17	package com.google.zxing.common;
18	
19	import java.util.Arrays;
20	
21	/**
22	 * <p>Represents a 2D matrix of bits. In function arguments below, and throughout the common
23	 * module, x is the column position, and y is the row position. The ordering is always x, y.
24	 * The origin is at the top-left.</p>
25	 *
26	 * <p>Internally the bits are represented in a 1-D array of 32-bit ints. However, each row begins
27	 * with a new int. This is done intentionally so that we can copy out a row into a BitArray very
28	 * efficiently.</p>
29	 *
30	 * <p>The ordering of bits is row-major. Within each int, the least significant bits are used first,
31	 * meaning they represent lower x values. This is compatible with BitArray's implementation.</p>
32	 *
33	 * @author Sean Owen
34	 * @author dswitkin@google.com (Daniel Switkin)
35	 */
36	public final class BitMatrix implements Cloneable {
37	
38	  private int width;
39	  private int height;
40	  private int rowSize;
41	  private int[] bits;
42	
43	  /**
44	   * Creates an empty square {@code BitMatrix}.
45	   *
46	   * @param dimension height and width
47	   */
48	  public BitMatrix(int dimension) {
49	    this(dimension, dimension);
50	  }
51	
52	  /**
53	   * Creates an empty {@code BitMatrix}.
54	   *
55	   * @param width bit matrix width
56	   * @param height bit matrix height
57	   */
58	  public BitMatrix(int width, int height) {
59	    if (width < 1 || height < 1) {
60	      throw new IllegalArgumentException("Both dimensions must be greater than 0");
61	    }
62	    this.width = width;
63	    this.height = height;
64	    this.rowSize = (width + 31) / 32;
65	    bits = new int[rowSize * height];
66	  }
67	
68	  private BitMatrix(int width, int height, int rowSize, int[] bits) {
69	    this.width = width;
70	    this.height = height;
71	    this.rowSize = rowSize;
72	    this.bits = bits;
73	  }
74	
75	  /**
76	   * Interprets a 2D array of booleans as a {@code BitMatrix}, where "true" means an "on" bit.
77	   *
78	   * @param image bits of the image, as a row-major 2D array. Elements are arrays representing rows
79	   * @return {@code BitMatrix} representation of image
80	   */
81	  public static BitMatrix parse(boolean[][] image) {
82	    int height = image.length;
83	    int width = image[0].length;
84	    BitMatrix bits = new BitMatrix(width, height);
85	    for (int i = 0; i < height; i++) {
86	      boolean[] imageI = image[i];
87	      for (int j = 0; j < width; j++) {
88	        if (imageI[j]) {
89	          bits.set(j, i);
90	        }
91	      }
92	    }
93	    return bits;
94	  }
95	
96	  public static BitMatrix parse(String stringRepresentation, String setString, String unsetString) {
97	    if (stringRepresentation == null) {
98	      throw new IllegalArgumentException();
99	    }
100	
101	    boolean[] bits = new boolean[stringRepresentation.length()];
102	    int bitsPos = 0;
103	    int rowStartPos = 0;
104	    int rowLength = -1;
105	    int nRows = 0;
106	    int pos = 0;
107	    while (pos < stringRepresentation.length()) {
108	      if (stringRepresentation.charAt(pos) == '\n' ||
109	          stringRepresentation.charAt(pos) == '\r') {
110	        if (bitsPos > rowStartPos) {
111	          if (rowLength == -1) {
112	            rowLength = bitsPos - rowStartPos;
113	          } else if (bitsPos - rowStartPos != rowLength) {
114	            throw new IllegalArgumentException("row lengths do not match");
115	          }
116	          rowStartPos = bitsPos;
117	          nRows++;
118	        }
119	        pos++;
120	      }  else if (stringRepresentation.startsWith(setString, pos)) {
121	        pos += setString.length();
122	        bits[bitsPos] = true;
123	        bitsPos++;
124	      } else if (stringRepresentation.startsWith(unsetString, pos)) {
125	        pos += unsetString.length();
126	        bits[bitsPos] = false;
127	        bitsPos++;
128	      } else {
129	        throw new IllegalArgumentException(
130	            "illegal character encountered: " + stringRepresentation.substring(pos));
131	      }
132	    }
133	
134	    // no EOL at end?
135	    if (bitsPos > rowStartPos) {
136	      if (rowLength == -1) {
137	        rowLength = bitsPos - rowStartPos;
138	      } else if (bitsPos - rowStartPos != rowLength) {
139	        throw new IllegalArgumentException("row lengths do not match");
140	      }
141	      nRows++;
142	    }
143	
144	    BitMatrix matrix = new BitMatrix(rowLength, nRows);
145	    for (int i = 0; i < bitsPos; i++) {
146	      if (bits[i]) {
147	        matrix.set(i % rowLength, i / rowLength);
148	      }
149	    }
150	    return matrix;
151	  }
152	
153	  /**
154	   * <p>Gets the requested bit, where true means black.</p>
155	   *
156	   * @param x The horizontal component (i.e. which column)
157	   * @param y The vertical component (i.e. which row)
158	   * @return value of given bit in matrix
159	   */
160	  public boolean get(int x, int y) {
161	    int offset = y * rowSize + (x / 32);
162	    return ((bits[offset] >>> (x & 0x1f)) & 1) != 0;
163	  }
164	
165	  /**
166	   * <p>Sets the given bit to true.</p>
167	   *
168	   * @param x The horizontal component (i.e. which column)
169	   * @param y The vertical component (i.e. which row)
170	   */
171	  public void set(int x, int y) {
172	    int offset = y * rowSize + (x / 32);
173	    bits[offset] |= 1 << (x & 0x1f);
174	  }
175	
176	  public void unset(int x, int y) {
177	    int offset = y * rowSize + (x / 32);
178	    bits[offset] &= ~(1 << (x & 0x1f));
179	  }
180	
181	  /**
182	   * <p>Flips the given bit.</p>
183	   *
184	   * @param x The horizontal component (i.e. which column)
185	   * @param y The vertical component (i.e. which row)
186	   */
187	  public void flip(int x, int y) {
188	    int offset = y * rowSize + (x / 32);
189	    bits[offset] ^= 1 << (x & 0x1f);
190	  }
191	
192	  /**
193	   * <p>Flips every bit in the matrix.</p>
194	   */
195	  public void flip() {
196	    int max = bits.length;
197	    for (int i = 0; i < max; i++) {
198	      bits[i] = ~bits[i];
199	    }
200	    // Clear padding bits beyond the logical width in the last int of each row
201	    int remainder = width % 32;
202	    if (remainder != 0) {
203	      int mask = (1 << remainder) - 1;
204	      for (int y = 0; y < height; y++) {
205	        int offset = y * rowSize + rowSize - 1;
206	        bits[offset] &= mask;
207	      }
208	    }
209	  }
210	
211	  /**
212	   * Exclusive-or (XOR): Flip the bit in this {@code BitMatrix} if the corresponding
213	   * mask bit is set.
214	   *
215	   * @param mask XOR mask
216	   */
217	  public void xor(BitMatrix mask) {
218	    if (width != mask.width || height != mask.height || rowSize != mask.rowSize) {
219	      throw new IllegalArgumentException("input matrix dimensions do not match");
220	    }
221	    BitArray rowArray = new BitArray(width);
222	    for (int y = 0; y < height; y++) {
223	      int offset = y * rowSize;
224	      int[] row = mask.getRow(y, rowArray).getBitArray();
225	      for (int x = 0; x < rowSize; x++) {
226	        bits[offset + x] ^= row[x];
227	      }
228	    }
229	  }
230	
231	  /**
232	   * Clears all bits (sets to false).
233	   */
234	  public void clear() {
235	    int max = bits.length;
236	    for (int i = 0; i < max; i++) {
237	      bits[i] = 0;
238	    }
239	  }
240	
241	  /**
242	   * <p>Sets a square region of the bit matrix to true.</p>
243	   *
244	   * @param left The horizontal position to begin at (inclusive)
245	   * @param top The vertical position to begin at (inclusive)
246	   * @param width The width of the region
247	   * @param height The height of the region
248	   */
249	  public void setRegion(int left, int top, int width, int height) {
250	    if (top < 0 || left < 0) {
251	      throw new IllegalArgumentException("Left and top must be nonnegative");
252	    }
253	    if (height < 1 || width < 1) {
254	      throw new IllegalArgumentException("Height and width must be at least 1");
255	    }
256	    int right = left + width;
257	    int bottom = top + height;
258	    if (bottom > this.height || right > this.width) {
259	      throw new IllegalArgumentException("The region must fit inside the matrix");
260	    }
261	    for (int y = top; y < bottom; y++) {
262	      int offset = y * rowSize;
263	      for (int x = left; x < right; x++) {
264	        bits[offset + (x / 32)] |= 1 << (x & 0x1f);
265	      }
266	    }
267	  }
268	
269	  /**
270	   * A fast method to retrieve one row of data from the matrix as a BitArray.
271	   *
272	   * @param y The row to retrieve
273	   * @param row An optional caller-allocated BitArray, will be allocated if null or too small
274	   * @return The resulting BitArray - this reference should always be used even when passing
275	   *         your own row
276	   */
277	  public BitArray getRow(int y, BitArray row) {
278	    if (row == null || row.getSize() < width) {
279	      row = new BitArray(width);
280	    } else {
281	      row.clear();
282	    }
283	    int offset = y * rowSize;
284	    for (int x = 0; x < rowSize; x++) {
285	      row.setBulk(x * 32, bits[offset + x]);
286	    }
287	    return row;
288	  }
289	
290	  /**
291	   * @param y row to set
292	   * @param row {@link BitArray} to copy from
293	   */
294	  public void setRow(int y, BitArray row) {
295	    System.arraycopy(row.getBitArray(), 0, bits, y * rowSize, rowSize);
296	  }
297	
298	  /**
299	   * Modifies this {@code BitMatrix} to represent the same but rotated the given degrees (0, 90, 180, 270)
300	   *
301	   * @param degrees number of degrees to rotate through counter-clockwise (0, 90, 180, 270)
302	   */
303	  public void rotate(int degrees) {
304	    switch (degrees % 360) {
305	      case 0:
306	        return;
307	      case 90:
308	        rotate90();
309	        return;
310	      case 180:
311	        rotate180();
312	        return;
313	      case 270:
314	        rotate90();
315	        rotate180();
316	        return;
317	    }
318	    throw new IllegalArgumentException("degrees must be a multiple of 0, 90, 180, or 270");
319	  }
320	
321	  /**
322	   * Modifies this {@code BitMatrix} to represent the same but rotated 180 degrees
323	   */
324	  public void rotate180() {
325	    BitArray topRow = new BitArray(width);
326	    BitArray bottomRow = new BitArray(width);
327	    int maxHeight = (height + 1) / 2;
328	    for (int i = 0; i < maxHeight; i++) {
329	      topRow = getRow(i, topRow);
330	      int bottomRowIndex = height - 1 - i;
331	      bottomRow = getRow(bottomRowIndex, bottomRow);
332	      topRow.reverse();
333	      bottomRow.reverse();
334	      setRow(i, bottomRow);
335	      setRow(bottomRowIndex, topRow);
336	    }
337	  }
338	
339	  /**
340	   * Modifies this {@code BitMatrix} to represent the same but rotated 90 degrees counterclockwise
341	   */
342	  public void rotate90() {
343	    int newWidth = height;
344	    int newHeight = width;
345	    int newRowSize = (newWidth + 31) / 32;
346	    int[] newBits = new int[newRowSize * newHeight];
347	
348	    for (int y = 0; y < height; y++) {
349	      for (int x = 0; x < width; x++) {
350	        int offset = y * rowSize + (x / 32);
351	        if (((bits[offset] >>> (x & 0x1f)) & 1) != 0) {
352	          int newOffset = (newHeight - 1 - x) * newRowSize + (y / 32);
353	          newBits[newOffset] |= 1 << (y & 0x1f);
354	        }
355	      }
356	    }
357	    width = newWidth;
358	    height = newHeight;
359	    rowSize = newRowSize;
360	    bits = newBits;
361	  }
362	
363	  /**
364	   * This is useful in detecting the enclosing rectangle of a 'pure' barcode.
365	   *
366	   * @return {@code left,top,width,height} enclosing rectangle of all 1 bits, or null if it is all white
367	   */
368	  public int[] getEnclosingRectangle() {
369	    int left = width;
370	    int top = height;
371	    int right = -1;
372	    int bottom = -1;
373	
374	    for (int y = 0; y < height; y++) {
375	      for (int x32 = 0; x32 < rowSize; x32++) {
376	        int theBits = bits[y * rowSize + x32];
377	        if (theBits != 0) {
378	          if (y < top) {
379	            top = y;
380	          }
381	          if (y > bottom) {
382	            bottom = y;
383	          }
384	          if (x32 * 32 < left) {
385	            int bit = 0;
386	            while ((theBits << (31 - bit)) == 0) {
387	              bit++;
388	            }
389	            if ((x32 * 32 + bit) < left) {
390	              left = x32 * 32 + bit;
391	            }
392	          }
393	          if (x32 * 32 + 31 > right) {
394	            int bit = 31;
395	            while ((theBits >>> bit) == 0) {
396	              bit--;
397	            }
398	            if ((x32 * 32 + bit) > right) {
399	              right = x32 * 32 + bit;
400	            }
401	          }
402	        }
403	      }
404	    }
405	
406	    if (right < left || bottom < top) {
407	      return null;
408	    }
409	
410	    return new int[] {left, top, right - left + 1, bottom - top + 1};
411	  }
412	
413	  /**
414	   * This is useful in detecting a corner of a 'pure' barcode.
415	   *
416	   * @return {@code x,y} coordinate of top-left-most 1 bit, or null if it is all white
417	   */
418	  public int[] getTopLeftOnBit() {
419	    int bitsOffset = 0;
420	    while (bitsOffset < bits.length && bits[bitsOffset] == 0) {
421	      bitsOffset++;
422	    }
423	    if (bitsOffset == bits.length) {
424	      return null;
425	    }
426	    int y = bitsOffset / rowSize;
427	    int x = (bitsOffset % rowSize) * 32;
428	
429	    int theBits = bits[bitsOffset];
430	    int bit = 0;
431	    while ((theBits << (31 - bit)) == 0) {
432	      bit++;
433	    }
434	    x += bit;
435	    return new int[] {x, y};
436	  }
437	
438	  public int[] getBottomRightOnBit() {
439	    int bitsOffset = bits.length - 1;
440	    while (bitsOffset >= 0 && bits[bitsOffset] == 0) {
441	      bitsOffset--;
442	    }
443	    if (bitsOffset < 0) {
444	      return null;
445	    }
446	
447	    int y = bitsOffset / rowSize;
448	    int x = (bitsOffset % rowSize) * 32;
449	
450	    int theBits = bits[bitsOffset];
451	    int bit = 31;
452	    while ((theBits >>> bit) == 0) {
453	      bit--;
454	    }
455	    x += bit;
456	
457	    return new int[] {x, y};
458	  }
459	
460	  /**
461	   * @return The width of the matrix
462	   */
463	  public int getWidth() {
464	    return width;
465	  }
466	
467	  /**
468	   * @return The height of the matrix
469	   */
470	  public int getHeight() {
471	    return height;
472	  }
473	
474	  /**
475	   * @return The row size of the matrix
476	   */
477	  public int getRowSize() {
478	    return rowSize;
479	  }
480	
481	  @Override
482	  public boolean equals(Object o) {
483	    if (!(o instanceof BitMatrix)) {
484	      return false;
485	    }
486	    BitMatrix other = (BitMatrix) o;
487	    return width == other.width && height == other.height && rowSize == other.rowSize &&
488	    Arrays.equals(bits, other.bits);
489	  }
490	
491	  @Override
492	  public int hashCode() {
493	    int hash = width;
494	    hash = 31 * hash + width;
495	    hash = 31 * hash + height;
496	    hash = 31 * hash + rowSize;
497	    hash = 31 * hash + Arrays.hashCode(bits);
498	    return hash;
499	  }
500	
501	  /**
502	   * @return string representation using "X" for set and " " for unset bits
503	   */
504	  @Override
505	  public String toString() {
506	    return toString("X ", "  ");
507	  }
508	
509	  /**
510	   * @param setString representation of a set bit
511	   * @param unsetString representation of an unset bit
512	   * @return string representation of entire matrix utilizing given strings
513	   */
514	  public String toString(String setString, String unsetString) {
515	    return buildToString(setString, unsetString, "\n");
516	  }
517	
518	  /**
519	   * @param setString representation of a set bit
520	   * @param unsetString representation of an unset bit
521	   * @param lineSeparator newline character in string representation
522	   * @return string representation of entire matrix utilizing given strings and line separator
523	   * @deprecated call {@link #toString(String,String)} only, which uses \n line separator always
524	   */
525	  @Deprecated
526	  public String toString(String setString, String unsetString, String lineSeparator) {
527	    return buildToString(setString, unsetString, lineSeparator);
528	  }
529	
530	  private String buildToString(String setString, String unsetString, String lineSeparator) {
531	    StringBuilder result = new StringBuilder(height * (width + 1));
532	    for (int y = 0; y < height; y++) {
533	      for (int x = 0; x < width; x++) {
534	        result.append(get(x, y) ? setString : unsetString);
535	      }
536	      result.append(lineSeparator);
537	    }
538	    return result.toString();
539	  }
540	
541	  @Override
542	  public BitMatrix clone() {
543	    return new BitMatrix(width, height, rowSize, bits.clone());
544	  }
545	
546	}
