17	package com.google.zxing.common;
18	
19	import com.google.zxing.Binarizer;
20	import com.google.zxing.LuminanceSource;
21	import com.google.zxing.NotFoundException;
22	
23	/**
24	 * This Binarizer implementation uses the old ZXing global histogram approach. It is suitable
25	 * for low-end mobile devices which don't have enough CPU or memory to use a local thresholding
26	 * algorithm. However, because it picks a global black point, it cannot handle difficult shadows
27	 * and gradients.
28	 *
29	 * Faster mobile devices and all desktop applications should probably use HybridBinarizer instead.
30	 *
31	 * @author dswitkin@google.com (Daniel Switkin)
32	 * @author Sean Owen
33	 */
34	public class GlobalHistogramBinarizer extends Binarizer {
35	
36	  private static final int LUMINANCE_BITS = 5;
37	  private static final int LUMINANCE_SHIFT = 8 - LUMINANCE_BITS;
38	  private static final int LUMINANCE_BUCKETS = 1 << LUMINANCE_BITS;
39	  private static final byte[] EMPTY = new byte[0];
40	
41	  private byte[] luminances;
42	  private final int[] buckets;
43	
44	  public GlobalHistogramBinarizer(LuminanceSource source) {
45	    super(source);
46	    luminances = EMPTY;
47	    buckets = new int[LUMINANCE_BUCKETS];
48	  }
49	
50	  // Applies simple sharpening to the row data to improve performance of the 1D Readers.
51	  @Override
52	  public BitArray getBlackRow(int y, BitArray row) throws NotFoundException {
53	    LuminanceSource source = getLuminanceSource();
54	    int width = source.getWidth();
55	    if (row == null || row.getSize() < width) {
56	      row = new BitArray(width);
57	    } else {
58	      row.clear();
59	    }
60	
61	    initArrays(width);
62	    byte[] localLuminances = source.getRow(y, luminances);
63	    int[] localBuckets = buckets;
64	    for (int x = 0; x < width; x++) {
65	      localBuckets[(localLuminances[x] & 0xff) >> LUMINANCE_SHIFT]++;
66	    }
67	    int blackPoint = estimateBlackPoint(localBuckets);
68	
69	    if (width < 3) {
70	      // Special case for very small images
71	      for (int x = 0; x < width; x++) {
72	        if ((localLuminances[x] & 0xff) < blackPoint) {
73	          row.set(x);
74	        }
75	      }
76	    } else {
77	      int left = localLuminances[0] & 0xff;
78	      int center = localLuminances[1] & 0xff;
79	      for (int x = 1; x < width - 1; x++) {
80	        int right = localLuminances[x + 1] & 0xff;
81	        // A simple -1 4 -1 box filter with a weight of 2.
82	        if (((center * 4) - left - right) / 2 < blackPoint) {
83	          row.set(x);
84	        }
85	        left = center;
86	        center = right;
87	      }
88	    }
89	    return row;
90	  }
91	
92	  // Does not sharpen the data, as this call is intended to only be used by 2D Readers.
93	  @Override
94	  public BitMatrix getBlackMatrix() throws NotFoundException {
95	    LuminanceSource source = getLuminanceSource();
96	    int width = source.getWidth();
97	    int height = source.getHeight();
98	    BitMatrix matrix = new BitMatrix(width, height);
99	
100	    // Quickly calculates the histogram by sampling four rows from the image. This proved to be
101	    // more robust on the blackbox tests than sampling a diagonal as we used to do.
102	    initArrays(width);
103	    int[] localBuckets = buckets;
104	    for (int y = 1; y < 5; y++) {
105	      int row = height * y / 5;
106	      byte[] localLuminances = source.getRow(row, luminances);
107	      int right = (width * 4) / 5;
108	      for (int x = width / 5; x < right; x++) {
109	        int pixel = localLuminances[x] & 0xff;
110	        localBuckets[pixel >> LUMINANCE_SHIFT]++;
111	      }
112	    }
113	    int blackPoint = estimateBlackPoint(localBuckets);
114	
115	    // We delay reading the entire image luminance until the black point estimation succeeds.
116	    // Although we end up reading four rows twice, it is consistent with our motto of
117	    // "fail quickly" which is necessary for continuous scanning.
118	    byte[] localLuminances = source.getMatrix();
119	    for (int y = 0; y < height; y++) {
120	      int offset = y * width;
121	      for (int x = 0; x < width; x++) {
122	        int pixel = localLuminances[offset + x] & 0xff;
123	        if (pixel < blackPoint) {
124	          matrix.set(x, y);
125	        }
126	      }
127	    }
128	
129	    return matrix;
130	  }
131	
132	  @Override
133	  public Binarizer createBinarizer(LuminanceSource source) {
134	    return new GlobalHistogramBinarizer(source);
135	  }
136	
137	  private void initArrays(int luminanceSize) {
138	    if (luminances.length < luminanceSize) {
139	      luminances = new byte[luminanceSize];
140	    }
141	    for (int x = 0; x < LUMINANCE_BUCKETS; x++) {
142	      buckets[x] = 0;
143	    }
144	  }
145	
146	  private static int estimateBlackPoint(int[] buckets) throws NotFoundException {
147	    // Find the tallest peak in the histogram.
148	    int numBuckets = buckets.length;
149	    int maxBucketCount = 0;
150	    int firstPeak = 0;
151	    int firstPeakSize = 0;
152	    for (int x = 0; x < numBuckets; x++) {
153	      if (buckets[x] > firstPeakSize) {
154	        firstPeak = x;
155	        firstPeakSize = buckets[x];
156	      }
157	      if (buckets[x] > maxBucketCount) {
158	        maxBucketCount = buckets[x];
159	      }
160	    }
161	
162	    // Find the second-tallest peak which is somewhat far from the tallest peak.
163	    int secondPeak = 0;
164	    int secondPeakScore = 0;
165	    for (int x = 0; x < numBuckets; x++) {
166	      int distanceToBiggest = x - firstPeak;
167	      // Encourage more distant second peaks by multiplying by square of distance.
168	      int score = buckets[x] * distanceToBiggest * distanceToBiggest;
169	      if (score > secondPeakScore) {
170	        secondPeak = x;
171	        secondPeakScore = score;
172	      }
173	    }
174	
175	    // Make sure firstPeak corresponds to the black peak.
176	    if (firstPeak > secondPeak) {
177	      int temp = firstPeak;
178	      firstPeak = secondPeak;
179	      secondPeak = temp;
180	    }
181	
182	    // If there is too little contrast in the image to pick a meaningful black point, throw rather
183	    // than waste time trying to decode the image, and risk false positives.
184	    if (secondPeak - firstPeak <= numBuckets / 16) {
185	      throw NotFoundException.getNotFoundInstance();
186	    }
187	
188	    // Find a valley between them that is low and closer to the white peak.
189	    int bestValley = secondPeak - 1;
190	    int bestValleyScore = -1;
191	    for (int x = secondPeak - 1; x > firstPeak; x--) {
192	      int fromFirst = x - firstPeak;
193	      int score = fromFirst * fromFirst * (secondPeak - x) * (maxBucketCount - buckets[x]);
194	      if (score > bestValleyScore) {
195	        bestValley = x;
196	        bestValleyScore = score;
197	      }
198	    }
199	
200	    return bestValley << LUMINANCE_SHIFT;
201	  }
202	
203	}
