126	    URL blockURL = context.getClassLoader().getResource("/private/uri-block-substrings.txt");
127	    if (blockURL == null) {
128	      blockedURLSubstrings = Collections.emptyList();
129	    } else {
130	      try {
131	        blockedURLSubstrings = Resources.readLines(blockURL, StandardCharsets.UTF_8);
132	      } catch (IOException ioe) {
133	        throw new ServletException(ioe);
134	      }
135	      log.info("Blocking URIs containing: " + blockedURLSubstrings);
136	    }
