141	    int maxEntries = Integer.parseInt(servletConfig.getInitParameter("maxEntries"));
142	
143	    String name = getClass().getSimpleName();
144	    timer = new Timer(name);
145	    destHostTracker = new DoSTracker(timer, name, maxAccessPerTime, accessTimeMS, maxEntries, null);
146	  }
