155	  @Override
156	  protected void doGet(HttpServletRequest request,
157	                       HttpServletResponse response) throws ServletException, IOException {
158	
159	    String imageURIString = request.getParameter("u");
160	    if (imageURIString == null || imageURIString.isEmpty()) {
161	      log.info("URI was empty");
162	      errorResponse(request, response, "badurl");
163	      return;
164	    }
165	
166	    // Remove any whitespace to sanitize; none is valid anyway
167	    imageURIString = WHITESPACE.matcher(imageURIString).replaceAll("");
168	
169	    if (!blockedURLSubstrings.isEmpty()) {
170	      for (CharSequence substring : blockedURLSubstrings) {
171	        if (imageURIString.contains(substring)) {
172	          log.info("Disallowed URI " + imageURIString);
173	          errorResponse(request, response, HttpServletResponse.SC_FORBIDDEN, "badurl");
174	          return;
175	        }
176	      }
177	    }
178	
179	    URI imageURI;
180	    try {
181	      imageURI = new URI(imageURIString);
182	      // Assume http: if not specified
183	      if (imageURI.getScheme() == null) {
184	        imageURI = new URI("http://" + imageURIString);
185	      }
186	    } catch (URISyntaxException e) {
187	      log.info("Error " + e + " while parsing URI: " + imageURIString);
188	      errorResponse(request, response, "badurl");
189	      return;
190	    }
191	
192	    // Shortcut for data URI
193	    if ("data".equals(imageURI.getScheme())) {
194	      BufferedImage image;
195	      try {
196	        image = ImageReader.readDataURIImage(imageURI);
197	      } catch (Exception e) {
198	        log.info("Error " + e + " while reading data URI: " + imageURIString);
199	        errorResponse(request, response, "badurl");
200	        return;
201	      }
202	      if (image == null) {
203	        log.info("Couldn't read data URI: " + imageURIString);
204	        errorResponse(request, response, "badimage");
205	        return;
206	      }
207	      try {
208	        processImage(image, request, response);
209	      } finally {
210	        image.flush();
211	      }
212	      return;
213	    }
214	
215	    String host = imageURI.getHost();
216	    // Also should parse for 172.x subnets
217	    if (host == null || host.startsWith("10.") || host.startsWith("192.168.") ||
218	        "127.0.0.1".equals(host) || "localhost".equals(host) ||
219	        destHostTracker.isBanned(host)) {
220	      errorResponse(request, response, HttpServletResponse.SC_FORBIDDEN, "badurl");
221	      return;
222	    }
223	
224	    URL imageURL;
225	    try {
226	      imageURL = imageURI.toURL();
227	    } catch (MalformedURLException ignored) {
228	      log.info("URI is not a URL: " + imageURIString);
229	      errorResponse(request, response, "badurl");
230	      return;
231	    }
232	
233	    String protocol = imageURL.getProtocol();
234	    if (!"http".equalsIgnoreCase(protocol) && !"https".equalsIgnoreCase(protocol)) {
235	      log.info("URL protocol was not valid: " + imageURIString);
236	      errorResponse(request, response, "badurl");
237	      return;
238	    }
239	
240	    HttpURLConnection connection;
241	    try {
242	      connection = (HttpURLConnection) imageURL.openConnection();
243	    } catch (IllegalArgumentException ignored) {
244	      log.info("URL could not be opened: " + imageURIString);
245	      errorResponse(request, response, "badurl");
246	      return;
247	    }
248	
249	    connection.setAllowUserInteraction(false);
250	    connection.setInstanceFollowRedirects(true);
251	    connection.setReadTimeout(5000);
252	    connection.setConnectTimeout(5000);
253	    connection.setRequestProperty(HttpHeaders.USER_AGENT, "zxing.org");
254	    connection.setRequestProperty(HttpHeaders.CONNECTION, "close");
255	
256	    try {
257	      connection.connect();
258	    } catch (Exception e) {
259	      // Encompasses lots of stuff, including
260	      //  java.net.SocketException, java.net.UnknownHostException,
261	      //  javax.net.ssl.SSLPeerUnverifiedException,
262	      //  org.apache.http.NoHttpResponseException,
263	      //  org.apache.http.client.ClientProtocolException,
264	      log.info("Error " + e + " connecting to " + imageURIString);
265	      errorResponse(request, response, "badurl");
266	      return;
267	    }
268	
269	    try (InputStream is = connection.getInputStream()) {
270	      if (connection.getResponseCode() != HttpServletResponse.SC_OK) {
271	        log.info("Unsuccessful return code " + connection.getResponseCode() + " from " + imageURIString);
272	        errorResponse(request, response, "badurl");
273	        return;
274	      }
275	      int contentLength = connection.getHeaderFieldInt(HttpHeaders.CONTENT_LENGTH, -1);
276	      if (contentLength <= 0) {
277	        log.info("Bad content length: " + imageURIString);
278	        errorResponse(request, response, HttpServletResponse.SC_LENGTH_REQUIRED, "badimage");
279	        return;
280	      }
281	      if (contentLength > MAX_IMAGE_SIZE) {
282	        log.info("Too large: " + imageURIString);
283	        errorResponse(request, response, HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE, "badimage");
284	        return;
285	      }
286	      // Assume we'll only handle image/* content types
287	      String contentType = connection.getContentType();
288	      if (contentType != null && !contentType.startsWith("image/")) {
289	        log.info("Wrong content type " + contentType + ": " + imageURIString);
290	        errorResponse(request, response, HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE, "badimage");
291	        return;
292	      }
293	
294	      log.info("Decoding " + imageURIString);
295	      processStream(is, request, response);
296	    } catch (IOException ioe) {
297	      log.info("Error " + ioe + " processing " + imageURIString);
298	      errorResponse(request, response, "badurl");
299	    } finally {
300	      connection.disconnect();
301	    }
302	
303	  }
