305	  @Override
306	  protected void doPost(HttpServletRequest request, HttpServletResponse response)
307	      throws ServletException, IOException {
308	    Collection<Part> parts;
309	    try {
310	      parts = request.getParts();
311	    } catch (Exception e) {
312	      // Includes IOException, InvalidContentTypeException, other parsing IllegalStateException
313	      log.info(e.toString());
314	      errorResponse(request, response, "badimage");
315	      return;
316	    }
317	    Part fileUploadPart = null;
318	    for (Part part : parts) {
319	      if (part.getHeader(HttpHeaders.CONTENT_DISPOSITION) != null) {
320	        fileUploadPart = part;
321	        break;
322	      }
323	    }
324	    if (fileUploadPart == null) {
325	      log.info("File upload was not multipart");
326	      errorResponse(request, response, "badimage");
327	    } else {
328	      log.info("Decoding uploaded file " + fileUploadPart.getSubmittedFileName());
329	      try (InputStream is = fileUploadPart.getInputStream()) {
330	        processStream(is, request, response);
331	      }
332	    }
333	  }
334	
335	  private static void processStream(InputStream is,
336	                                    HttpServletRequest request,
337	                                    HttpServletResponse response) throws ServletException, IOException {
338	
339	    BufferedImage image;
340	    try {
341	      image = ImageIO.read(is);
342	    } catch (Exception e) {
343	      // Many possible failures from JAI, so just catch anything as a failure
344	      log.info(e.toString());
345	      errorResponse(request, response, "badimage");
346	      return;
347	    }
348	    if (image == null) {
349	      errorResponse(request, response, "badimage");
350	      return;
351	    }
352	    try {
353	      int height = image.getHeight();
354	      int width = image.getWidth();
355	      if (height <= 1 || width <= 1) {
356	        log.info("Dimensions too small: " + width + 'x' + height);
357	        errorResponse(request, response, "badimage");
358	        return;
359	      } else if (height * width > MAX_PIXELS) {
360	        log.info("Dimensions too large: " + width + 'x' + height);
361	        errorResponse(request, response, HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE, "badimage");
362	        return;
363	      }
364	
365	      processImage(image, request, response);
366	    } finally {
367	      image.flush();
368	    }
369	  }
370	
371	  private static void processImage(BufferedImage image,
372	                                   HttpServletRequest request,
373	                                   HttpServletResponse response) throws IOException, ServletException {
374	
375	    LuminanceSource source = new BufferedImageLuminanceSource(image);
376	    BinaryBitmap bitmap = new BinaryBitmap(new GlobalHistogramBinarizer(source));
377	    Collection<Result> results = new ArrayList<>(1);
378	
379	    try {
380	
381	      Reader reader = new MultiFormatReader();
382	      ReaderException savedException = null;
383	      try {
384	        // Look for multiple barcodes
385	        MultipleBarcodeReader multiReader = new GenericMultipleBarcodeReader(reader);
386	        Result[] theResults = multiReader.decodeMultiple(bitmap, HINTS);
387	        if (theResults != null) {
388	          results.addAll(Arrays.asList(theResults));
389	        }
390	      } catch (ReaderException re) {
391	        savedException = re;
392	      }
393	
394	      if (results.isEmpty() && !Thread.currentThread().isInterrupted()) {
395	        try {
396	          // Look for pure barcode
397	          Result theResult = reader.decode(bitmap, HINTS_PURE);
398	          if (theResult != null) {
399	            results.add(theResult);
400	          }
401	        } catch (ReaderException re) {
402	          savedException = re;
403	        }
404	      }
405	
406	      if (results.isEmpty() && !Thread.currentThread().isInterrupted()) {
407	        try {
408	          // Look for normal barcode in photo
409	          Result theResult = reader.decode(bitmap, HINTS);
410	          if (theResult != null) {
411	            results.add(theResult);
412	          }
413	        } catch (ReaderException re) {
414	          savedException = re;
415	        }
416	      }
417	
418	      if (results.isEmpty() && !Thread.currentThread().isInterrupted()) {
419	        try {
420	          // Try again with other binarizer
421	          BinaryBitmap hybridBitmap = new BinaryBitmap(new HybridBinarizer(source));
422	          Result theResult = reader.decode(hybridBitmap, HINTS);
423	          if (theResult != null) {
424	            results.add(theResult);
425	          }
426	        } catch (ReaderException re) {
427	          savedException = re;
428	        }
429	      }
430	
431	      if (results.isEmpty()) {
432	        try {
433	          throw savedException == null ? NotFoundException.getNotFoundInstance() : savedException;
434	        } catch (FormatException | ChecksumException e) {
435	          errorResponse(request, response, "format");
436	        } catch (ReaderException e) { // Including NotFoundException
437	          errorResponse(request, response, "notfound");
438	        }
439	        return;
440	      }
441	
442	    } catch (RuntimeException re) {
443	      // Call out unexpected errors in the log clearly
444	      log.log(Level.WARNING, "Unexpected exception from library", re);
445	      throw new ServletException(re);
446	    }
447	
448	    String fullParameter = request.getParameter("full");
449	    boolean minimalOutput = fullParameter != null && !Boolean.parseBoolean(fullParameter);
450	    if (minimalOutput) {
451	      response.setContentType(MediaType.PLAIN_TEXT_UTF_8.toString());
452	      response.setCharacterEncoding(StandardCharsets.UTF_8.name());
453	      try (Writer out = new OutputStreamWriter(response.getOutputStream(), StandardCharsets.UTF_8)) {
454	        for (Result result : results) {
455	          out.write(result.getText());
456	          out.write('\n');
457	        }
458	      }
459	    } else {
460	      request.setAttribute("results", results);
461	      request.getRequestDispatcher("decoderesult.jspx").forward(request, response);
462	    }
463	  }
464	  private static void errorResponse(HttpServletRequest request,
465	                                    HttpServletResponse response,
466	                                    String key) throws ServletException, IOException {
467	    errorResponse(request, response, HttpServletResponse.SC_BAD_REQUEST, key);
468	  }
469	
470	  private static void errorResponse(HttpServletRequest request,
471	                                    HttpServletResponse response,
472	                                    int httpStatus,
473	                                    String key) throws ServletException, IOException {
474	    Locale locale = request.getLocale();
475	    if (locale == null) {
476	      locale = Locale.ENGLISH;
477	    }
478	    ResourceBundle bundle = ResourceBundle.getBundle("Strings", locale);
479	    String title = bundle.getString("response.error." + key + ".title");
480	    String text = bundle.getString("response.error." + key + ".text");
481	    request.setAttribute("title", title);
482	    request.setAttribute("text", text);
483	    RequestDispatcher dispatcher = request.getRequestDispatcher("response.jspx");
484	    if (dispatcher == null) {
485	      log.warning("Can't obtain RequestDispatcher");
486	    } else {
487	      response.setStatus(httpStatus);
488	      dispatcher.forward(request, response);
489	    }
490	  }
