30	import jakarta.servlet.ServletRequest;
31	import jakarta.servlet.annotation.WebServlet;
32	import jakarta.servlet.http.HttpServlet;
33	import jakarta.servlet.http.HttpServletRequest;
34	import jakarta.servlet.http.HttpServletResponse;
35	import java.io.ByteArrayOutputStream;
36	import java.io.IOException;
37	import java.nio.charset.Charset;
38	import java.nio.charset.StandardCharsets;
39	import java.util.Collection;
40	import java.util.EnumMap;
41	import java.util.Locale;
42	import java.util.Map;
43	
44	/**
45	 * A reimplementation of the
46	 * <a href="https://google-developers.appspot.com/chart/infographics/docs/qr_codes">
47	 * Google Chart Server's QR code encoder</a>, which is now deprecated. See
48	 * <a href="https://github.com/zxing/zxing/wiki/Chart-Server-Parameters">the chart server
49	 * parameters wiki page</a> for docs.
50	 *
51	 * @author Sean Owen
52	 */
53	@WebServlet({"/w/chart", "/w/chart.png", "/w/chart.gif", "/w/chart.jpg", "/w/chart.jpeg"})
54	public final class ChartServlet extends HttpServlet {
55	
56	  private static final int MAX_DIMENSION = 4096;
57	  private static final Collection<Charset> SUPPORTED_OUTPUT_ENCODINGS = ImmutableSet.<Charset>builder()
58	      .add(StandardCharsets.UTF_8).add(StandardCharsets.ISO_8859_1).add(Charset.forName("Shift_JIS")).build();
59	
60	  @Override
61	  protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
62	    doEncode(request, response, false);
63	  }
64	
65	  @Override
66	  protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
67	    doEncode(request, response, true);
68	  }
69	
70	  private static void doEncode(HttpServletRequest request, HttpServletResponse response, boolean isPost)
71	      throws IOException {
72	
73	    ChartServletRequestParameters parameters;
74	    try {
75	      parameters = doParseParameters(request, isPost);
76	    } catch (IllegalArgumentException | NullPointerException e) {
77	      response.sendError(HttpServletResponse.SC_BAD_REQUEST, e.toString());
78	      return;
79	    }
80	
81	    Map<EncodeHintType,Object> hints = new EnumMap<>(EncodeHintType.class);
82	    hints.put(EncodeHintType.MARGIN, parameters.getMargin());
83	    if (!StandardCharsets.ISO_8859_1.equals(parameters.getOutputEncoding())) {
84	      // Only set if not QR code default
85	      hints.put(EncodeHintType.CHARACTER_SET, parameters.getOutputEncoding().name());
86	    }
87	    hints.put(EncodeHintType.ERROR_CORRECTION, parameters.getEcLevel());
88	
89	    BitMatrix matrix;
90	    try {
91	      matrix = new QRCodeWriter().encode(parameters.getText(),
92	                                         BarcodeFormat.QR_CODE,
93	                                         parameters.getWidth(),
94	                                         parameters.getHeight(),
95	                                         hints);
96	    } catch (WriterException we) {
97	      response.sendError(HttpServletResponse.SC_BAD_REQUEST, we.toString());
98	      return;
99	    }
100	
101	    String requestURI = request.getRequestURI();
102	    if (requestURI == null) {
103	      response.sendError(HttpServletResponse.SC_BAD_REQUEST);
104	      return;
105	    }
106	    int lastDot = requestURI.lastIndexOf('.');
107	    String imageFormat;
108	    if (lastDot > 0) {
109	      imageFormat = requestURI.substring(lastDot + 1).toUpperCase(Locale.ROOT);
110	      // Special-case jpg -> JPEG
111	      if ("JPG".equals(imageFormat)) {
112	        imageFormat = "JPEG";
113	      }
114	    } else {
115	      imageFormat = "PNG";
116	    }
117	
118	    String contentType;
119	    switch (imageFormat) {
120	      case "PNG":
121	        contentType = "image/png";
122	        break;
123	      case "JPEG":
124	        contentType = "image/jpeg";
125	        break;
126	      case "GIF":
127	        contentType = "image/gif";
128	        break;
129	      default:
130	        throw new IllegalArgumentException("Unknown format " + imageFormat);
131	    }
132	
133	    ByteArrayOutputStream imageOut = new ByteArrayOutputStream(1024);
134	    MatrixToImageWriter.writeToStream(matrix, imageFormat, imageOut);
135	    byte[] imageData = imageOut.toByteArray();
136	
137	    response.setContentType(contentType);
138	    response.setContentLength(imageData.length);
139	    response.setHeader("Cache-Control", "public");
140	    response.getOutputStream().write(imageData);
141	  }
142	
143	  private static ChartServletRequestParameters doParseParameters(ServletRequest request, boolean readBody)
144	      throws IOException {
145	
146	    String chartType = request.getParameter("cht");
147	    Preconditions.checkArgument(chartType == null || "qr".equals(chartType), "Bad type");
148	
149	    String widthXHeight = request.getParameter("chs");
150	    Preconditions.checkNotNull(widthXHeight, "No size");
151	    int xIndex = widthXHeight.indexOf('x');
152	    Preconditions.checkArgument(xIndex >= 0, "Bad size");
153	
154	    int width = Integer.parseInt(widthXHeight.substring(0, xIndex));
155	    int height = Integer.parseInt(widthXHeight.substring(xIndex + 1));
156	    Preconditions.checkArgument(width > 0 && height > 0, "Bad size");
157	    Preconditions.checkArgument(width <= MAX_DIMENSION && height <= MAX_DIMENSION, "Bad size");
158	
159	    String outputEncodingName = request.getParameter("choe");
160	    Charset outputEncoding;
161	    if (outputEncodingName == null) {
162	      outputEncoding = StandardCharsets.UTF_8;
163	    } else {
164	      outputEncoding = Charset.forName(outputEncodingName);
165	      Preconditions.checkArgument(SUPPORTED_OUTPUT_ENCODINGS.contains(outputEncoding), "Bad output encoding");
166	    }
167	
168	    ErrorCorrectionLevel ecLevel = ErrorCorrectionLevel.L;
169	    int margin = 4;
170	
171	    String ldString = request.getParameter("chld");
172	    if (ldString != null) {
173	      int pipeIndex = ldString.indexOf('|');
174	      if (pipeIndex < 0) {
175	        // Only an EC level
176	        ecLevel = ErrorCorrectionLevel.valueOf(ldString);
177	      } else {
178	        ecLevel = ErrorCorrectionLevel.valueOf(ldString.substring(0, pipeIndex));
179	        margin = Integer.parseInt(ldString.substring(pipeIndex + 1));
180	        Preconditions.checkArgument(margin > 0, "Bad margin");
181	      }
182	    }
183	
184	    String text;
185	    if (readBody) {
186	      text = CharStreams.toString(request.getReader());
187	    } else {
188	      text = request.getParameter("chl");
189	    }
190	    Preconditions.checkArgument(text != null && !text.isEmpty(), "No input");
191	
192	    return new ChartServletRequestParameters(width, height, outputEncoding, ecLevel, margin, text);
193	  }
194	
195	}
