17	package com.google.zxing;
18	
19	/**
20	 * This class is used to help decode images from files which arrive as RGB data from
21	 * an ARGB pixel array.
22	 *
23	 * @author dswitkin@google.com (Daniel Switkin)
24	 * @author Betaminos
25	 */
26	public final class RGBLuminanceSource extends GrayscaleLuminanceSource {
27	
28	  public RGBLuminanceSource(int width, int height, int[] pixels) {
29	    super(width, height, toGrayscale(width, height, pixels));
30	  }
31	
32	  private static byte[] toGrayscale(int width, int height, int[] pixels) {
33	    int size = width * height;
34	    if (pixels == null || pixels.length < size) {
35	      throw new IllegalArgumentException("Pixel array length is less than width * height");
36	    }
37	    byte[] luminances = new byte[size];
38	    for (int offset = 0; offset < size; offset++) {
39	      int pixel = pixels[offset];
40	      int r = (pixel >> 16) & 0xff; // red
41	      int g2 = (pixel >> 7) & 0x1fe; // 2 * green
42	      int b = pixel & 0xff; // blue
43	      // Calculate green-favouring average cheaply
44	      luminances[offset] = (byte) ((r + g2 + b) / 4);
45	    }
46	    return luminances;
47	  }
48	}
