18	
19	/**
20	 * This class is used to help decode images from files which arrive as a grayscale
21	 * pixel array.
22	 *
23	 * @author dswitkin@google.com (Daniel Switkin)
24	 * @author Betaminos
25	 */
26	public class GrayscaleLuminanceSource extends LuminanceSource {
27	
28	  private final byte[] luminances;
29	  private final int dataWidth;
30	  private final int dataHeight;
31	  private final int left;
32	  private final int top;
33	
34	  public GrayscaleLuminanceSource(int width, int height, byte[] pixels) {
35	    super(width, height);
36	    luminances = pixels;
37	    dataWidth = width;
38	    dataHeight = height;
39	    left = 0;
40	    top = 0;
41	  }
42	
43	  private GrayscaleLuminanceSource(byte[] pixels,
44	                                   int dataWidth,
45	                                   int dataHeight,
46	                                   int left,
47	                                   int top,
48	                                   int width,
49	                                   int height) {
50	    super(width, height);
51	    if (left < 0 || top < 0 || width < 0 || height < 0 ||
52	        width > dataWidth - left || height > dataHeight - top) {
53	      throw new IllegalArgumentException("Crop rectangle does not fit within image data.");
54	    }
55	    this.luminances = pixels;
56	    this.dataWidth = dataWidth;
57	    this.dataHeight = dataHeight;
58	    this.left = left;
59	    this.top = top;
60	  }
61	
62	  @Override
63	  public byte[] getRow(int y, byte[] row) {
64	    if (y < 0 || y >= getHeight()) {
65	      throw new IllegalArgumentException("Requested row is outside the image: " + y);
66	    }
67	    int width = getWidth();
68	    if (row == null || row.length < width) {
69	      row = new byte[width];
70	    }
71	    int offset = (y + top) * dataWidth + left;
72	    System.arraycopy(luminances, offset, row, 0, width);
73	    return row;
74	  }
75	
76	  @Override
77	  public byte[] getMatrix() {
78	    int width = getWidth();
79	    int height = getHeight();
80	
81	    // If the caller asks for the entire underlying image, save the copy and give them the
82	    // original data. The docs specifically warn that result.length must be ignored.
83	    if (width == dataWidth && height == dataHeight) {
84	      return luminances;
85	    }
86	
87	    int area = width * height;
88	    byte[] matrix = new byte[area];
89	    int inputOffset = top * dataWidth + left;
90	
91	    // If the width matches the full width of the underlying data, perform a single copy.
92	    if (width == dataWidth) {
93	      System.arraycopy(luminances, inputOffset, matrix, 0, area);
94	      return matrix;
95	    }
96	
97	    // Otherwise copy one cropped row at a time.
98	    for (int y = 0; y < height; y++) {
99	      int outputOffset = y * width;
100	      System.arraycopy(luminances, inputOffset, matrix, outputOffset, width);
101	      inputOffset += dataWidth;
102	    }
103	    return matrix;
104	  }
105	
106	  @Override
107	  public boolean isCropSupported() {
108	    return true;
109	  }
110	
111	  @Override
112	  public LuminanceSource crop(int left, int top, int width, int height) {
113	    return new GrayscaleLuminanceSource(luminances,
114	                                        dataWidth,
115	                                        dataHeight,
116	                                        this.left + left,
117	                                        this.top + top,
118	                                        width,
119	                                        height);
120	  }
121	
122	  @Override
123	  public boolean isRotateSupported() {
124	    return true;
125	  }
126	
127	  @Override
128	  public LuminanceSource rotateCounterClockwise() {
129	    byte[] rotated = new byte[luminances.length];
130	    for (int y = 0; y < dataHeight; y++) {
131	      for (int x = 0; x < dataWidth; x++) {
132	        int i = (y * dataWidth) + x;
133	        int x2 = y;
134	        int y2 = dataWidth - 1 - x;
135	        int j = (y2 * dataHeight) + x2;
136	        rotated[j] = luminances[i];
137	      }
138	    }
139	    int newWidth = getHeight();
140	    int newHeight = getWidth();
141	    int newLeft = top;
142	    int newTop = dataWidth - (left + getWidth());
143	    return new GrayscaleLuminanceSource(rotated, dataHeight, dataWidth, newLeft, newTop, newWidth, newHeight);
144	  }
145	}
