17	package com.google.zxing.web;
18	
19	import com.google.common.base.Preconditions;
20	
21	import jakarta.servlet.Filter;
22	import jakarta.servlet.FilterChain;
23	import jakarta.servlet.FilterConfig;
24	import jakarta.servlet.ServletException;
25	import jakarta.servlet.ServletRequest;
26	import jakarta.servlet.ServletResponse;
27	import jakarta.servlet.http.HttpServletRequest;
28	import jakarta.servlet.http.HttpServletResponse;
29	import java.io.IOException;
30	import java.util.Timer;
31	import java.util.concurrent.TimeUnit;
32	
33	/**
34	 * A simplistic {@link Filter} that rejects requests from hosts that are sending too many
35	 * requests in too short a time.
36	 *
37	 * @author Sean Owen
38	 */
39	public abstract class DoSFilter implements Filter {
40	
41	  private Timer timer;
42	  private DoSTracker sourceAddrTracker;
43	
44	  @Override
45	  public void init(FilterConfig filterConfig) {
46	    int maxAccessPerTime = Integer.parseInt(filterConfig.getInitParameter("maxAccessPerTime"));
47	    Preconditions.checkArgument(maxAccessPerTime > 0);
48	
49	    int accessTimeSec = Integer.parseInt(filterConfig.getInitParameter("accessTimeSec"));
50	    Preconditions.checkArgument(accessTimeSec > 0);
51	    long accessTimeMS = TimeUnit.MILLISECONDS.convert(accessTimeSec, TimeUnit.SECONDS);
52	
53	    String maxEntriesValue = filterConfig.getInitParameter("maxEntries");
54	    int maxEntries = Integer.MAX_VALUE;
55	    if (maxEntriesValue != null) {
56	      maxEntries = Integer.parseInt(maxEntriesValue);
57	      Preconditions.checkArgument(maxEntries > 0);
58	    }
59	
60	    String maxLoadValue = filterConfig.getInitParameter("maxLoad");
61	    Double maxLoad = null;
62	    if (maxLoadValue != null) {
63	      maxLoad = Double.valueOf(maxLoadValue);
64	      Preconditions.checkArgument(maxLoad > 0.0);
65	    }
66	
67	    String name = getClass().getSimpleName();
68	    timer = new Timer(name);
69	    sourceAddrTracker = new DoSTracker(timer, name, maxAccessPerTime, accessTimeMS, maxEntries, maxLoad);
70	  }
71	
72	  @Override
73	  public void doFilter(ServletRequest request,
74	                       ServletResponse response,
75	                       FilterChain chain) throws IOException, ServletException {
76	    if (isBanned((HttpServletRequest) request)) {
77	      HttpServletResponse servletResponse = (HttpServletResponse) response;
78	      // Send very short response as requests may be very frequent
79	      servletResponse.setStatus(429); // 429 = Too Many Requests from RFC 6585
80	      servletResponse.getWriter().write("Forbidden");
81	    } else {
82	      chain.doFilter(request, response);
83	    }
84	  }
85	
86	  private boolean isBanned(HttpServletRequest request) {
87	    String remoteHost = request.getHeader("x-forwarded-for");
88	    if (remoteHost != null) {
89	      int comma = remoteHost.indexOf(',');
90	      if (comma >= 0) {
91	        remoteHost = remoteHost.substring(0, comma);
92	      }
93	      remoteHost = remoteHost.trim();
94	    }
95	    // Non-short-circuit "|" below is on purpose
96	    return
97	      (remoteHost != null && sourceAddrTracker.isBanned(remoteHost)) |
98	      sourceAddrTracker.isBanned(request.getRemoteAddr());
99	  }
100	
101	  @Override
102	  public void destroy() {
103	    if (timer != null) {
104	      timer.cancel();
105	    }
106	  }
107	
108	}
