19	import com.google.common.util.concurrent.SimpleTimeLimiter;
20	import com.google.common.util.concurrent.TimeLimiter;
21	
22	import jakarta.servlet.Filter;
23	import jakarta.servlet.FilterChain;
24	import jakarta.servlet.FilterConfig;
25	import jakarta.servlet.ServletException;
26	import jakarta.servlet.ServletRequest;
27	import jakarta.servlet.ServletResponse;
28	import jakarta.servlet.annotation.WebFilter;
29	import jakarta.servlet.annotation.WebInitParam;
30	import jakarta.servlet.http.HttpServletResponse;
31	import java.io.IOException;
32	import java.util.concurrent.Callable;
33	import java.util.concurrent.ExecutionException;
34	import java.util.concurrent.Executors;
35	import java.util.concurrent.ExecutorService;
36	import java.util.concurrent.TimeoutException;
37	import java.util.concurrent.TimeUnit;
38	
39	/**
40	 * Protect the decode endpoint from long-running requests.
41	 */
42	@WebFilter(urlPatterns = {"/w/decode"}, initParams = {
43	  @WebInitParam(name = "timeoutSec", value = "10"),
44	})
45	public final class TimeoutFilter implements Filter {
46	
47	  private ExecutorService executorService;
48	  private TimeLimiter timeLimiter;
49	  private int timeoutSec;
50	
51	  @Override
52	  public void init(FilterConfig filterConfig) {
53	    executorService = Executors.newCachedThreadPool();
54	    timeLimiter = SimpleTimeLimiter.create(executorService);
55	    timeoutSec = Integer.parseInt(filterConfig.getInitParameter("timeoutSec"));
56	  }
57	
58	  @Override
59	  public void doFilter(ServletRequest request,
60	                       ServletResponse response,
61	                       FilterChain chain) throws IOException, ServletException {
62	    try {
63	      timeLimiter.callWithTimeout(new Callable<Void>() {
64	        @Override
65	        public Void call() throws Exception {
66	          chain.doFilter(request, response);
67	          return null;
68	        }
69	      }, timeoutSec, TimeUnit.SECONDS);
70	    } catch (TimeoutException | InterruptedException e) {
71	      HttpServletResponse servletResponse = (HttpServletResponse) response;
72	      servletResponse.setStatus(HttpServletResponse.SC_REQUEST_TIMEOUT);
73	      servletResponse.getWriter().write("Request took too long");
74	    } catch (ExecutionException e) {
75	      if (e.getCause() instanceof ServletException) {
76	        throw (ServletException) e.getCause();
77	      }
78	      if (e.getCause() instanceof IOException) {
79	        throw (IOException) e.getCause();
80	      }
81	      throw new ServletException(e.getCause());
82	    }
83	  }
84	
85	  @Override
86	  public void destroy() {
87	    if (executorService != null) {
88	      executorService.shutdownNow();
89	    }
90	  }
91	
92	}
