31	 * file or stream. Provided here instead of core since it depends on
32	 * Java SE libraries.
33	 *
34	 * @author Sean Owen
35	 */
36	public final class MatrixToImageWriter {
37	
38	  private static final MatrixToImageConfig DEFAULT_CONFIG = new MatrixToImageConfig();
39	
40	  private MatrixToImageWriter() {}
41	
42	  /**
43	   * Renders a {@link BitMatrix} as an image, where "false" bits are rendered
44	   * as white, and "true" bits are rendered as black. Uses default configuration.
45	   *
46	   * @param matrix {@link BitMatrix} to write
47	   * @return {@link BufferedImage} representation of the input
48	   */
49	  public static BufferedImage toBufferedImage(BitMatrix matrix) {
50	    return toBufferedImage(matrix, DEFAULT_CONFIG);
51	  }
52	
53	  /**
54	   * As {@link #toBufferedImage(BitMatrix)}, but allows customization of the output.
55	   *
56	   * @param matrix {@link BitMatrix} to write
57	   * @param config output configuration
58	   * @return {@link BufferedImage} representation of the input
59	   */
60	  public static BufferedImage toBufferedImage(BitMatrix matrix, MatrixToImageConfig config) {
61	    int width = matrix.getWidth();
62	    int height = matrix.getHeight();
63	    BufferedImage image = new BufferedImage(width, height, config.getBufferedImageColorModel());
64	    int onColor = config.getPixelOnColor();
65	    int offColor = config.getPixelOffColor();
66	    int[] rowPixels = new int[width];
67	    BitArray row = new BitArray(width);
68	    for (int y = 0; y < height; y++) {
69	      row = matrix.getRow(y, row);
70	      for (int x = 0; x < width; x++) {
71	        rowPixels[x] = row.get(x) ? onColor : offColor;
72	      }
73	      image.setRGB(0, y, width, 1, rowPixels, 0, width);
74	    }
75	    return image;
76	  }
