21	import java.awt.Graphics2D;
22	import java.awt.geom.AffineTransform;
23	import java.awt.image.BufferedImage;
24	import java.awt.image.WritableRaster;
25	
26	/**
27	 * This LuminanceSource implementation is meant for J2SE clients and our blackbox unit tests.
28	 *
29	 * @author dswitkin@google.com (Daniel Switkin)
30	 * @author Sean Owen
31	 * @author code@elektrowolle.de (Wolfgang Jung)
32	 */
33	public final class BufferedImageLuminanceSource extends LuminanceSource {
34	
35	  private static final double MINUS_45_IN_RADIANS = -0.7853981633974483; // Math.toRadians(-45.0)
36	
37	  private final BufferedImage image;
38	  private final int left;
39	  private final int top;
40	
41	  public BufferedImageLuminanceSource(BufferedImage image) {
42	    this(image, 0, 0, image.getWidth(), image.getHeight());
43	  }
44	
45	  public BufferedImageLuminanceSource(BufferedImage image, int left, int top, int width, int height) {
46	    super(width, height);
47	
48	    int sourceWidth = image.getWidth();
49	    int sourceHeight = image.getHeight();
50	    if (left < 0 || top < 0 || width < 0 || height < 0 ||
51	        width > sourceWidth - left || height > sourceHeight - top) {
52	      throw new IllegalArgumentException("Crop rectangle does not fit within image data.");
53	    }
54	
55	    if (image.getType() == BufferedImage.TYPE_BYTE_GRAY) {
56	      this.image = image;
57	    } else {
58	
59	      this.image = new BufferedImage(sourceWidth, sourceHeight, BufferedImage.TYPE_BYTE_GRAY);
60	
61	      WritableRaster raster = this.image.getRaster();
62	      int[] buffer = new int[width];
63	      for (int y = top; y < top + height; y++) {
64	        image.getRGB(left, y, width, 1, buffer, 0, sourceWidth);
65	        for (int x = 0; x < width; x++) {
66	          int pixel = buffer[x];
67	
68	          // The color of fully-transparent pixels is irrelevant. They are often, technically, fully-transparent
69	          // black (0 alpha, and then 0 RGB). They are often used, of course as the "white" area in a
70	          // barcode image. Force any such pixel to be white:
71	          if ((pixel & 0xFF000000) == 0) {
72	            // white, so we know its luminance is 255
73	            buffer[x] = 0xFF;
74	          } else {
75	            // .299R + 0.587G + 0.114B (YUV/YIQ for PAL and NTSC),
76	            // (306*R) >> 10 is approximately equal to R*0.299, and so on.
77	            // 0x200 >> 10 is 0.5, it implements rounding.
78	            buffer[x] =
79	              (306 * ((pixel >> 16) & 0xFF) +
80	                601 * ((pixel >> 8) & 0xFF) +
81	                117 * (pixel & 0xFF) +
82	                0x200) >> 10;
83	          }
84	        }
85	        raster.setPixels(left, y, width, 1, buffer);
86	      }
87	
88	    }
89	    this.left = left;
90	    this.top = top;
91	  }
92	
93	  @Override
94	  public byte[] getRow(int y, byte[] row) {
95	    if (y < 0 || y >= getHeight()) {
96	      throw new IllegalArgumentException("Requested row is outside the image: " + y);
97	    }
98	    int width = getWidth();
99	    if (row == null || row.length < width) {
100	      row = new byte[width];
101	    }
102	    // The underlying raster of image consists of bytes with the luminance values
103	    image.getRaster().getDataElements(left, top + y, width, 1, row);
104	    return row;
105	  }
106	
107	  @Override
108	  public byte[] getMatrix() {
109	    int width = getWidth();
110	    int height = getHeight();
111	    int area = width * height;
112	    byte[] matrix = new byte[area];
113	    // The underlying raster of image consists of area bytes with the luminance values
114	    image.getRaster().getDataElements(left, top, width, height, matrix);
115	    return matrix;
116	  }
117	
118	  @Override
119	  public boolean isCropSupported() {
120	    return true;
121	  }
122	
123	  @Override
124	  public LuminanceSource crop(int left, int top, int width, int height) {
125	    return new BufferedImageLuminanceSource(image, this.left + left, this.top + top, width, height);
126	  }
127	
128	  /**
129	   * This is always true, since the image is a gray-scale image.
130	   *
131	   * @return true
132	   */
133	  @Override
134	  public boolean isRotateSupported() {
135	    return true;
136	  }
137	
138	  @Override
139	  public LuminanceSource rotateCounterClockwise() {
140	    int sourceWidth = image.getWidth();
141	    int sourceHeight = image.getHeight();
142	
143	    // Rotate 90 degrees counterclockwise.
144	    AffineTransform transform = new AffineTransform(0.0, -1.0, 1.0, 0.0, 0.0, sourceWidth);
145	
146	    // Note width/height are flipped since we are rotating 90 degrees.
147	    BufferedImage rotatedImage = new BufferedImage(sourceHeight, sourceWidth, BufferedImage.TYPE_BYTE_GRAY);
148	
149	    // Draw the original image into rotated, via transformation
150	    Graphics2D g = rotatedImage.createGraphics();
151	    g.drawImage(image, transform, null);
152	    g.dispose();
153	
154	    // Maintain the cropped region, but rotate it too.
155	    int width = getWidth();
156	    return new BufferedImageLuminanceSource(rotatedImage, top, sourceWidth - (left + width), getHeight(), width);
157	  }
158	
159	  @Override
160	  public LuminanceSource rotateCounterClockwise45() {
161	    int width = getWidth();
162	    int height = getHeight();
163	
164	    int oldCenterX = left + width / 2;
165	    int oldCenterY = top + height / 2;
166	
167	    // Rotate 45 degrees counterclockwise.
168	    AffineTransform transform = AffineTransform.getRotateInstance(MINUS_45_IN_RADIANS, oldCenterX, oldCenterY);
169	
170	    int sourceDimension = Math.max(image.getWidth(), image.getHeight());
171	    BufferedImage rotatedImage = new BufferedImage(sourceDimension, sourceDimension, BufferedImage.TYPE_BYTE_GRAY);
172	
173	    // Draw the original image into rotated, via transformation
174	    Graphics2D g = rotatedImage.createGraphics();
175	    g.drawImage(image, transform, null);
176	    g.dispose();
177	
178	    int halfDimension = Math.max(width, height) / 2;
179	    int newLeft = Math.max(0, oldCenterX - halfDimension);
180	    int newTop = Math.max(0, oldCenterY - halfDimension);
181	    int newRight = Math.min(sourceDimension - 1, oldCenterX + halfDimension);
182	    int newBottom = Math.min(sourceDimension - 1, oldCenterY + halfDimension);
183	
184	    return new BufferedImageLuminanceSource(rotatedImage, newLeft, newTop, newRight - newLeft, newBottom - newTop);
185	  }
186	
187	}
